using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;using System.Globalization;using Ace.DynastyCOT;
class LongPathTimingChecks {
 static double Median(List<double> a){a.Sort();return a[a.Count/2];}
 static List<double> Sample(Action read){var a=new List<double>();read();for(int i=0;i<21;i++){var watch=Stopwatch.StartNew();for(int k=0;k<100;k++)read();a.Add(watch.Elapsed.TotalMilliseconds/100);}return a;}
 static void Main(string[] args){string root=args[0];if(!File.Exists(Path.Combine(root,".cot-fixture")))throw new Exception("Marked fixture required");string shortFile=Path.Combine(root,"read.json"),longFile=Path.Combine(root,new string('a',120),new string('b',120),"read.json");var text=new string('x',1024);StorageDirectory.CreateDirectory(StoragePath.GetDirectoryName(longFile));StorageFile.WriteAllText(shortFile,text);StorageFile.WriteAllText(longFile,text);foreach(var item in new[]{Tuple.Create("before_short",(Action)(()=>{if(File.ReadAllText(shortFile)!=text)throw new Exception();})),Tuple.Create("after_short",(Action)(()=>{if(StorageFile.ReadAllText(shortFile)!=text)throw new Exception();})),Tuple.Create("after_long",(Action)(()=>{if(StorageFile.ReadAllText(longFile)!=text)throw new Exception();}))}){var a=Sample(item.Item2);Console.WriteLine(item.Item1+" median_ms="+Median(a).ToString("F6",CultureInfo.InvariantCulture)+" max_ms="+a[a.Count-1].ToString("F6",CultureInfo.InvariantCulture));}}
}
